import {
  Component,
  ChangeDetectionStrategy,
  OnInit,
} from '@angular/core';
import { CommonModule } from '@angular/common';
import { MatIconModule } from '@angular/material/icon';
import { ActivatedRoute, Router } from '@angular/router';
import { NotificationService } from '../../../../shared/services/notification.service';

@Component({
  selector: 'app-event-redirect-page',
  standalone: true,
  imports: [CommonModule, MatIconModule],
  template: `
    <div class="redirect-container">
      <mat-icon class="spinner-icon">sync</mat-icon>
      <p>リダイレクト中...</p>
    </div>
  `,
  styles: [`
    :host {
      display: flex;
      align-items: center;
      justify-content: center;
      min-height: 100vh;
      min-height: 100dvh;
      background: #f7f7fa;
      font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    }
    .redirect-container {
      text-align: center;
      color: #556;
    }
    .spinner-icon {
      font-size: 36px;
      width: 36px;
      height: 36px;
      color: #ff9800;
      animation: spin 1.2s linear infinite;
    }
    p {
      margin-top: 12px;
      font-size: 14px;
      font-weight: 500;
    }
    @keyframes spin {
      100% { transform: rotate(360deg); }
    }
  `],
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class EventRedirectPageComponent implements OnInit {
  constructor(
    private route: ActivatedRoute,
    private router: Router,
    private notification: NotificationService,
  ) {}

  ngOnInit(): void {
    const id = this.route.snapshot.paramMap.get('id');
    if (!id) {
      this.notification.error('イベントIDが見つかりません');
      return;
    }
    // 現時点ではすべて複数人予定調整ページへリダイレクト
    this.notification.info('リダイレクト中...');
    this.router.navigate(['/multiple/event', id]);
  }
}
